            self.asi8, tz, ambiguous=ambiguous, nonexistent=nonexistent
        )
        new_dates = new_dates.view(DT64NS_DTYPE)
        dtype = tz_to_dtype(tz)
        self.freq = None  # Reset frequency when localizing
        return self._simple_new(new_dates, dtype=dtype, freq=self.freq)

    # Ensure to check inferred frequency after timezone is changed
    new_dates_inferred_freq = self.inferred_freq
    if new_dates_inferred_freq is None:
        self.freq = None  # Drop frequency if not inferrable
    else:
        self.freq = new_dates_inferred_freq

    return self._simple_new(new_dates, dtype=dtype, freq=self.freq)
